export type EventCallback = (payload: any) => void;

export class EventBus {
  private subscribers: Map<string, EventCallback[]> = new Map();

  publish(event: string, payload: any): void {
    const subs = this.subscribers.get(event) || [];
    // Call subscribers asynchronously to avoid blocking publisher
    for (const cb of subs) {
      try {
        // Use setImmediate-like via setTimeout 0 to decouple
        setTimeout(() => {
          try {
            cb(payload);
          } catch (err) {
            // Swallow errors to avoid breaking others
            // In a real system, we'd log this
          }
        }, 0);
      } catch {
        // ignore
      }
    }
  }

  subscribe(event: string, callback: EventCallback): void {
    const subs = this.subscribers.get(event) || [];
    subs.push(callback);
    this.subscribers.set(event, subs);
  }
}

import { randomUUID } from 'crypto';

export interface User {
  id: string;
  name: string;
  email: string;
}

export class UserService {
  private store: Map<string, User> = new Map();

  create(input: { name: string; email: string }): User {
    const user: User = { id: randomUUID(), name: input.name, email: input.email };
    this.store.set(user.id, user);
    return user;
  }

  getById(id: string): User | undefined {
    return this.store.get(id);
  }

  getAll(): User[] {
    return Array.from(this.store.values());
  }

  update(id: string, updates: Partial<Omit<User, 'id'>>): User | undefined {
    const existing = this.store.get(id);
    if (!existing) return undefined;
    const updated: User = { ...existing, ...updates, id: existing.id };
    this.store.set(id, updated);
    return updated;
  }

  delete(id: string): boolean {
    return this.store.delete(id);
  }
}

import { randomUUID } from 'crypto';

export interface Project {
  id: string;
  name: string;
  description?: string;
  memberIds: string[];
}

export class ProjectService {
  private store: Map<string, Project> = new Map();

  create(input: { name: string; description?: string; memberIds?: string[] }): Project {
    const project: Project = {
      id: randomUUID(),
      name: input.name,
      description: input.description,
      memberIds: input.memberIds ? Array.from(new Set(input.memberIds)) : [],
    };
    this.store.set(project.id, project);
    return project;
  }

  getById(id: string): Project | undefined {
    return this.store.get(id);
  }

  getAll(): Project[] {
    return Array.from(this.store.values());
  }

  update(id: string, updates: Partial<Omit<Project, 'id'>>): Project | undefined {
    const existing = this.store.get(id);
    if (!existing) return undefined;
    const updated: Project = {
      ...existing,
      ...updates,
      id: existing.id,
      memberIds: updates.memberIds ? Array.from(new Set(updates.memberIds)) : existing.memberIds,
    };
    this.store.set(id, updated);
    return updated;
  }

  delete(id: string): boolean {
    return this.store.delete(id);
  }

  addMember(projectId: string, userId: string): Project | undefined {
    const project = this.store.get(projectId);
    if (!project) return undefined;
    if (!project.memberIds.includes(userId)) {
      project.memberIds.push(userId);
    }
    return project;
  }

  removeMember(projectId: string, userId: string): Project | undefined {
    const project = this.store.get(projectId);
    if (!project) return undefined;
    project.memberIds = project.memberIds.filter((id) => id !== userId);
    return project;
  }
}

import { randomUUID } from 'crypto';
import { EventBus } from '../event-bus';

export type TaskStatus = 'todo' | 'in-progress' | 'done';

export interface Task {
  id: string;
  title: string;
  description?: string;
  status: TaskStatus;
  assigneeId?: string;
  projectId: string;
}

export class TaskService {
  private store: Map<string, Task> = new Map();
  constructor(private bus: EventBus) {}

  create(input: { title: string; description?: string; projectId: string; assigneeId?: string }): Task {
    const task: Task = {
      id: randomUUID(),
      title: input.title,
      description: input.description,
      projectId: input.projectId,
      assigneeId: input.assigneeId,
      status: 'todo',
    };
    this.store.set(task.id, task);
    if (task.assigneeId) {
      this.bus.publish('task.assigned', { taskId: task.id, taskTitle: task.title, assigneeId: task.assigneeId });
    }
    return task;
  }

  getById(id: string): Task | undefined {
    return this.store.get(id);
  }

  getAll(): Task[] {
    return Array.from(this.store.values());
  }

  update(id: string, updates: Partial<Omit<Task, 'id'>>): Task | undefined {
    const existing = this.store.get(id);
    if (!existing) return undefined;
    const prevAssignee = existing.assigneeId;
    const prevStatus = existing.status;
    const updated: Task = { ...existing, ...updates, id: existing.id };
    this.store.set(id, updated);
    if (updates.assigneeId && updates.assigneeId !== prevAssignee) {
      this.bus.publish('task.assigned', { taskId: updated.id, taskTitle: updated.title, assigneeId: updates.assigneeId });
    }
    if (updates.status && updates.status !== prevStatus) {
      this.bus.publish('task.statusChanged', {
        taskId: updated.id,
        taskTitle: updated.title,
        assigneeId: updated.assigneeId,
        oldStatus: prevStatus,
        newStatus: updates.status,
      });
    }
    return updated;
  }

  delete(id: string): boolean {
    return this.store.delete(id);
  }

  assign(id: string, assigneeId: string): Task | undefined {
    const task = this.store.get(id);
    if (!task) return undefined;
    task.assigneeId = assigneeId;
    this.bus.publish('task.assigned', { taskId: task.id, taskTitle: task.title, assigneeId });
    return task;
  }

  changeStatus(id: string, newStatus: TaskStatus): Task | undefined {
    const task = this.store.get(id);
    if (!task) return undefined;
    const allowed: Record<TaskStatus, TaskStatus | null> = {
      'todo': 'in-progress',
      'in-progress': 'done',
      'done': null,
    };
    const next = allowed[task.status];
    if (next !== newStatus) {
      // Only allow forward one step transitions
      return undefined;
    }
    const oldStatus = task.status;
    task.status = newStatus;
    this.bus.publish('task.statusChanged', {
      taskId: task.id,
      taskTitle: task.title,
      assigneeId: task.assigneeId,
      oldStatus,
      newStatus,
    });
    return task;
  }

  getByProject(projectId: string): Task[] {
    return Array.from(this.store.values()).filter((t) => t.projectId === projectId);
  }
}

import { randomUUID } from 'crypto';
import { EventBus } from '../event-bus';

export interface Comment {
  id: string;
  taskId: string;
  authorId: string;
  body: string;
  createdAt: number; // epoch ms
}

export class CommentService {
  private store: Map<string, Comment> = new Map();
  // For publishing taskTitle and authorName, the CommentService must not call other services.
  // Therefore, router can pass in minimal lookup functions at creation, or we send only IDs.
  // Per spec, CommentService publishes: { commentId, taskId, taskTitle, authorId, authorName }.
  // To respect constraints, we accept provider callbacks for resolving names at event time from the router layer.
  constructor(private bus: EventBus, private providers: { getTaskTitle: (taskId: string) => string | undefined; getUserName: (userId: string) => string | undefined }) {}

  create(input: { taskId: string; authorId: string; body: string }): Comment {
    const comment: Comment = {
      id: randomUUID(),
      taskId: input.taskId,
      authorId: input.authorId,
      body: input.body,
      createdAt: Date.now(),
    };
    this.store.set(comment.id, comment);
    const taskTitle = this.providers.getTaskTitle(comment.taskId);
    const authorName = this.providers.getUserName(comment.authorId);
    this.bus.publish('comment.added', {
      commentId: comment.id,
      taskId: comment.taskId,
      taskTitle,
      authorId: comment.authorId,
      authorName,
    });
    return comment;
  }

  getById(id: string): Comment | undefined {
    return this.store.get(id);
  }

  getByTask(taskId: string): Comment[] {
    return Array.from(this.store.values()).filter((c) => c.taskId === taskId);
  }

  delete(id: string): boolean {
    return this.store.delete(id);
  }
}

import { randomUUID } from 'crypto';
import { EventBus } from '../event-bus';

export interface Notification {
  id: string;
  userId: string;
  message: string;
  read: boolean;
  createdAt: number; // epoch ms
}

export class NotificationService {
  private store: Map<string, Notification> = new Map();

  constructor(private bus: EventBus, private providers: { getTaskAssigneeId: (taskId: string) => string | undefined }) {
    // Subscribe to events
    bus.subscribe('task.assigned', (payload: any) => {
      const { taskId, taskTitle, assigneeId } = payload || {};
      if (!assigneeId) return;
      const message = `Task assigned: "${taskTitle || taskId}"`;
      this.createNotification(assigneeId, message);
    });

    bus.subscribe('task.statusChanged', (payload: any) => {
      const { taskId, taskTitle, assigneeId, oldStatus, newStatus } = payload || {};
      if (!assigneeId) return;
      const message = `Task status changed: "${taskTitle || taskId}" ${oldStatus} -> ${newStatus}`;
      this.createNotification(assigneeId, message);
    });

    bus.subscribe('comment.added', (payload: any) => {
      const { taskId, taskTitle, authorName } = payload || {};
      const assigneeId = this.providers.getTaskAssigneeId(taskId);
      if (!assigneeId) return;
      const message = `New comment on task "${taskTitle || taskId}" by ${authorName || 'someone'}`;
      this.createNotification(assigneeId, message);
    });
  }

  private createNotification(userId: string, message: string): Notification {
    const notif: Notification = {
      id: randomUUID(),
      userId,
      message,
      read: false,
      createdAt: Date.now(),
    };
    this.store.set(notif.id, notif);
    return notif;
  }

  getByUser(userId: string): Notification[] {
    return Array.from(this.store.values()).filter((n) => n.userId === userId);
  }

  markAsRead(id: string): Notification | undefined {
    const n = this.store.get(id);
    if (!n) return undefined;
    n.read = true;
    return n;
  }
}

import http, { IncomingMessage, ServerResponse } from 'http';
import { URL } from 'url';
import { UserService } from './services/user-service';
import { ProjectService } from './services/project-service';
import { TaskService, TaskStatus } from './services/task-service';
import { CommentService } from './services/comment-service';
import { NotificationService } from './services/notification-service';

export interface RouterDeps {
  userService: UserService;
  projectService: ProjectService;
  taskService: TaskService;
  commentService: CommentService;
  notificationService: NotificationService;
}

function parseBody(req: IncomingMessage): Promise<any> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    req.on('data', (c) => chunks.push(c));
    req.on('end', () => {
      if (chunks.length === 0) return resolve(undefined);
      const raw = Buffer.concat(chunks).toString('utf8');
      try {
        resolve(raw ? JSON.parse(raw) : undefined);
      } catch (err) {
        reject(new Error('Invalid JSON body'));
      }
    });
    req.on('error', reject);
  });
}

function send(res: ServerResponse, code: number, data: any) {
  const body = data !== undefined ? JSON.stringify(data) : '';
  res.statusCode = code;
  res.setHeader('Content-Type', 'application/json');
  res.end(body);
}

export function createServer(deps: RouterDeps) {
  const server = http.createServer(async (req, res) => {
    const method = req.method || 'GET';
    const url = new URL(req.url || '/', 'http://localhost');
    const path = url.pathname;

    try {
      // Users
      if (method === 'GET' && path === '/users') {
        return send(res, 200, deps.userService.getAll());
      }
      if (method === 'POST' && path === '/users') {
        const body = await parseBody(req);
        const created = deps.userService.create({ name: body.name, email: body.email });
        return send(res, 201, created);
      }
      if (method === 'GET' && path.startsWith('/users/')) {
        const id = path.split('/')[2];
        const u = deps.userService.getById(id);
        if (!u) return send(res, 404, { error: 'Not found' });
        return send(res, 200, u);
      }
      if (method === 'PUT' && path.startsWith('/users/')) {
        const id = path.split('/')[2];
        const body = await parseBody(req);
        const updated = deps.userService.update(id, { name: body.name, email: body.email });
        if (!updated) return send(res, 404, { error: 'Not found' });
        return send(res, 200, updated);
      }
      if (method === 'DELETE' && path.startsWith('/users/')) {
        const id = path.split('/')[2];
        const ok = deps.userService.delete(id);
        if (!ok) return send(res, 404, { error: 'Not found' });
        return send(res, 204, undefined);
      }

      // Projects
      if (method === 'GET' && path === '/projects') {
        return send(res, 200, deps.projectService.getAll());
      }
      if (method === 'POST' && path === '/projects') {
        const body = await parseBody(req);
        const created = deps.projectService.create({ name: body.name, description: body.description });
        return send(res, 201, created);
      }
      if (method === 'GET' && path.startsWith('/projects/')) {
        const id = path.split('/')[2];
        const p = deps.projectService.getById(id);
        if (!p) return send(res, 404, { error: 'Not found' });
        return send(res, 200, p);
      }
      if (method === 'PUT' && path.startsWith('/projects/')) {
        const id = path.split('/')[2];
        const body = await parseBody(req);
        const updated = deps.projectService.update(id, { name: body.name, description: body.description, memberIds: body.memberIds });
        if (!updated) return send(res, 404, { error: 'Not found' });
        return send(res, 200, updated);
      }
      if (method === 'DELETE' && path.startsWith('/projects/')) {
        const id = path.split('/')[2];
        const ok = deps.projectService.delete(id);
        if (!ok) return send(res, 404, { error: 'Not found' });
        return send(res, 204, undefined);
      }
      if (method === 'POST' && path.match(/^\/projects\/[^/]+\/members$/)) {
        const id = path.split('/')[2];
        const body = await parseBody(req);
        const updated = deps.projectService.addMember(id, body.userId);
        if (!updated) return send(res, 404, { error: 'Not found' });
        return send(res, 200, updated);
      }
      if (method === 'DELETE' && path.match(/^\/projects\/[^/]+\/members$/)) {
        const id = path.split('/')[2];
        const body = await parseBody(req); // assume body contains userId
        const updated = deps.projectService.removeMember(id, body.userId);
        if (!updated) return send(res, 404, { error: 'Not found' });
        return send(res, 200, updated);
      }

      // Tasks
      if (method === 'GET' && path === '/tasks') {
        const projectId = url.searchParams.get('projectId');
        if (!projectId) return send(res, 400, { error: 'projectId is required' });
        return send(res, 200, deps.taskService.getByProject(projectId));
      }
      if (method === 'POST' && path === '/tasks') {
        const body = await parseBody(req);
        const created = deps.taskService.create({ title: body.title, description: body.description, projectId: body.projectId, assigneeId: body.assigneeId });
        return send(res, 201, created);
      }
      if (method === 'GET' && path.startsWith('/tasks/')) {
        const id = path.split('/')[2];
        const t = deps.taskService.getById(id);
        if (!t) return send(res, 404, { error: 'Not found' });
        return send(res, 200, t);
      }
      if (method === 'PUT' && path.match(/^\/tasks\/[^/]+$/)) {
        const id = path.split('/')[2];
        const body = await parseBody(req);
        const updated = deps.taskService.update(id, { title: body.title, description: body.description, status: body.status as TaskStatus, assigneeId: body.assigneeId, projectId: body.projectId });
        if (!updated) return send(res, 404, { error: 'Not found or invalid update' });
        return send(res, 200, updated);
      }
      if (method === 'DELETE' && path.match(/^\/tasks\/[^/]+$/)) {
        const id = path.split('/')[2];
        const ok = deps.taskService.delete(id);
        if (!ok) return send(res, 404, { error: 'Not found' });
        return send(res, 204, undefined);
      }
      if (method === 'PUT' && path.match(/^\/tasks\/[^/]+\/status$/)) {
        const id = path.split('/')[2];
        const body = await parseBody(req);
        const updated = deps.taskService.changeStatus(id, body.status as TaskStatus);
        if (!updated) return send(res, 400, { error: 'Invalid status transition or task not found' });
        return send(res, 200, updated);
      }
      if (method === 'PUT' && path.match(/^\/tasks\/[^/]+\/assign$/)) {
        const id = path.split('/')[2];
        const body = await parseBody(req);
        const updated = deps.taskService.assign(id, body.assigneeId);
        if (!updated) return send(res, 404, { error: 'Not found' });
        return send(res, 200, updated);
      }

      // Comments
      if (method === 'GET' && path === '/comments') {
        const taskId = url.searchParams.get('taskId');
        if (!taskId) return send(res, 400, { error: 'taskId is required' });
        return send(res, 200, deps.commentService.getByTask(taskId));
      }
      if (method === 'POST' && path === '/comments') {
        const body = await parseBody(req);
        const created = deps.commentService.create({ taskId: body.taskId, authorId: body.authorId, body: body.body });
        return send(res, 201, created);
      }
      if (method === 'GET' && path.startsWith('/comments/')) {
        const id = path.split('/')[2];
        const c = deps.commentService.getById(id);
        if (!c) return send(res, 404, { error: 'Not found' });
        return send(res, 200, c);
      }
      if (method === 'DELETE' && path.startsWith('/comments/')) {
        const id = path.split('/')[2];
        const ok = deps.commentService.delete(id);
        if (!ok) return send(res, 404, { error: 'Not found' });
        return send(res, 204, undefined);
      }

      // Notifications
      if (method === 'GET' && path === '/notifications') {
        const userId = url.searchParams.get('userId');
        if (!userId) return send(res, 400, { error: 'userId is required' });
        return send(res, 200, deps.notificationService.getByUser(userId));
      }
      if (method === 'PUT' && path.match(/^\/notifications\/[^/]+\/read$/)) {
        const id = path.split('/')[2];
        const updated = deps.notificationService.markAsRead(id);
        if (!updated) return send(res, 404, { error: 'Not found' });
        return send(res, 200, updated);
      }

      // Not found
      send(res, 404, { error: 'Route not found' });
    } catch (err: any) {
      send(res, 400, { error: err?.message || 'Bad request' });
    }
  });
  return server;
}

import { EventBus } from './event-bus';
import { UserService } from './services/user-service';
import { ProjectService } from './services/project-service';
