import http, { IncomingMessage, ServerResponse } from 'http';
import { URL } from 'url';
import { UserService } from './services/user-service';
import { ProjectService } from './services/project-service';
import { TaskService, TaskStatus } from './services/task-service';
import { CommentService } from './services/comment-service';
import { NotificationService } from './services/notification-service';

export interface RouterDeps {
  userService: UserService;
  projectService: ProjectService;
  taskService: TaskService;
  commentService: CommentService;
  notificationService: NotificationService;
}

function parseBody(req: IncomingMessage): Promise<any> {
  return new Promise((resolve, reject) => {
    const chunks: any[] = [];
    req.on('data', (c: any) => chunks.push(c));
    req.on('end', () => {
      if (chunks.length === 0) return resolve(undefined);
      const raw = Buffer.concat(chunks as any).toString('utf8');
      try {
        resolve(raw ? JSON.parse(raw) : undefined);
      } catch (err) {
        reject(new Error('Invalid JSON body'));
      }
    });
    req.on('error', reject);
  });
}

function send(res: ServerResponse, code: number, data: any) {
  const body = data !== undefined ? JSON.stringify(data) : '';
  res.statusCode = code;
  res.setHeader('Content-Type', 'application/json');
  res.end(body);
}

export function createServer(deps: RouterDeps) {
  const server = http.createServer(async (req: any, res: any) => {
    const method = req.method || 'GET';
    const url = new URL(req.url || '/', 'http://localhost');
    const path = url.pathname;

    try {
      // Users
      if (method === 'GET' && path === '/users') {
        return send(res, 200, deps.userService.getAll());
      }
      if (method === 'POST' && path === '/users') {
        const body = await parseBody(req);
        const created = deps.userService.create({ name: body.name, email: body.email });
        return send(res, 201, created);
      }
      if (method === 'GET' && path.startsWith('/users/')) {
        const id = path.split('/')[2];
        const u = deps.userService.getById(id);
        if (!u) return send(res, 404, { error: 'Not found' });
        return send(res, 200, u);
      }
      if (method === 'PUT' && path.startsWith('/users/')) {
        const id = path.split('/')[2];
        const body = await parseBody(req);
        const updated = deps.userService.update(id, { name: body.name, email: body.email });
        if (!updated) return send(res, 404, { error: 'Not found' });
        return send(res, 200, updated);
      }
      if (method === 'DELETE' && path.startsWith('/users/')) {
        const id = path.split('/')[2];
        const ok = deps.userService.delete(id);
        if (!ok) return send(res, 404, { error: 'Not found' });
        return send(res, 204, undefined);
      }

      // Projects
      if (method === 'GET' && path === '/projects') {
        return send(res, 200, deps.projectService.getAll());
      }
      if (method === 'POST' && path === '/projects') {
        const body = await parseBody(req);
        const created = deps.projectService.create({ name: body.name, description: body.description });
        return send(res, 201, created);
      }
      if (method === 'GET' && path.startsWith('/projects/')) {
        const id = path.split('/')[2];
        const p = deps.projectService.getById(id);
        if (!p) return send(res, 404, { error: 'Not found' });
        return send(res, 200, p);
      }
      if (method === 'PUT' && path.startsWith('/projects/')) {
        const id = path.split('/')[2];
        const body = await parseBody(req);
        const updated = deps.projectService.update(id, { name: body.name, description: body.description, memberIds: body.memberIds });
        if (!updated) return send(res, 404, { error: 'Not found' });
        return send(res, 200, updated);
      }
      if (method === 'DELETE' && path.startsWith('/projects/')) {
        const id = path.split('/')[2];
        const ok = deps.projectService.delete(id);
        if (!ok) return send(res, 404, { error: 'Not found' });
        return send(res, 204, undefined);
      }
      if (method === 'POST' && path.match(/^\/projects\/[^/]+\/members$/)) {
        const id = path.split('/')[2];
        const body = await parseBody(req);
        const updated = deps.projectService.addMember(id, body.userId);
        if (!updated) return send(res, 404, { error: 'Not found' });
        return send(res, 200, updated);
      }
      if (method === 'DELETE' && path.match(/^\/projects\/[^/]+\/members$/)) {
        const id = path.split('/')[2];
        const body = await parseBody(req); // assume body contains userId
        const updated = deps.projectService.removeMember(id, body.userId);
        if (!updated) return send(res, 404, { error: 'Not found' });
        return send(res, 200, updated);
      }

      // Tasks
      if (method === 'GET' && path === '/tasks') {
        const projectId = url.searchParams.get('projectId');
        if (!projectId) return send(res, 400, { error: 'projectId is required' });
        return send(res, 200, deps.taskService.getByProject(projectId));
      }
      if (method === 'POST' && path === '/tasks') {
        const body = await parseBody(req);
        const created = deps.taskService.create({ title: body.title, description: body.description, projectId: body.projectId, assigneeId: body.assigneeId });
        return send(res, 201, created);
      }
      if (method === 'GET' && path.startsWith('/tasks/')) {
        const id = path.split('/')[2];
        const t = deps.taskService.getById(id);
        if (!t) return send(res, 404, { error: 'Not found' });
        return send(res, 200, t);
      }
      if (method === 'PUT' && path.match(/^\/tasks\/[^/]+$/)) {
        const id = path.split('/')[2];
        const body = await parseBody(req);
        const updated = deps.taskService.update(id, { title: body.title, description: body.description, status: body.status as TaskStatus, assigneeId: body.assigneeId, projectId: body.projectId });
        if (!updated) return send(res, 404, { error: 'Not found or invalid update' });
        return send(res, 200, updated);
      }
      if (method === 'DELETE' && path.match(/^\/tasks\/[^/]+$/)) {
        const id = path.split('/')[2];
        const ok = deps.taskService.delete(id);
        if (!ok) return send(res, 404, { error: 'Not found' });
        return send(res, 204, undefined);
      }
      if (method === 'PUT' && path.match(/^\/tasks\/[^/]+\/status$/)) {
        const id = path.split('/')[2];
        const body = await parseBody(req);
        const updated = deps.taskService.changeStatus(id, body.status as TaskStatus);
        if (!updated) return send(res, 400, { error: 'Invalid status transition or task not found' });
        return send(res, 200, updated);
      }
      if (method === 'PUT' && path.match(/^\/tasks\/[^/]+\/assign$/)) {
        const id = path.split('/')[2];
        const body = await parseBody(req);
        const updated = deps.taskService.assign(id, body.assigneeId);
        if (!updated) return send(res, 404, { error: 'Not found' });
        return send(res, 200, updated);
      }

      // Comments
      if (method === 'GET' && path === '/comments') {
        const taskId = url.searchParams.get('taskId');
        if (!taskId) return send(res, 400, { error: 'taskId is required' });
        return send(res, 200, deps.commentService.getByTask(taskId));
      }
      if (method === 'POST' && path === '/comments') {
        const body = await parseBody(req);
        const created = deps.commentService.create({ taskId: body.taskId, authorId: body.authorId, body: body.body });
        return send(res, 201, created);
      }
      if (method === 'GET' && path.startsWith('/comments/')) {
        const id = path.split('/')[2];
        const c = deps.commentService.getById(id);
        if (!c) return send(res, 404, { error: 'Not found' });
        return send(res, 200, c);
      }
      if (method === 'DELETE' && path.startsWith('/comments/')) {
        const id = path.split('/')[2];
        const ok = deps.commentService.delete(id);
        if (!ok) return send(res, 404, { error: 'Not found' });
        return send(res, 204, undefined);
      }

      // Notifications
      if (method === 'GET' && path === '/notifications') {
        const userId = url.searchParams.get('userId');
        if (!userId) return send(res, 400, { error: 'userId is required' });
        return send(res, 200, deps.notificationService.getByUser(userId));
      }
      if (method === 'PUT' && path.match(/^\/notifications\/[^/]+\/read$/)) {
        const id = path.split('/')[2];
        const updated = deps.notificationService.markAsRead(id);
        if (!updated) return send(res, 404, { error: 'Not found' });
        return send(res, 200, updated);
      }

      // Not found
      send(res, 404, { error: 'Route not found' });
    } catch (err: any) {
      send(res, 400, { error: err?.message || 'Bad request' });
    }
  });
  return server;
}

import { EventBus } from './event-bus';
import { UserService } from './services/user-service';
import { ProjectService } from './services/project-service';
import { TaskService } from './services/task-service';
import { CommentService } from './services/comment-service';
import { NotificationService } from './services/notification-service';
import { createServer } from './router';
import http from 'http';

function request(method: string, path: string, body?: any): Promise<any> {
  return new Promise((resolve, reject) => {
    const data = body ? JSON.stringify(body) : undefined;
    const req = http.request({ hostname: 'localhost', port: 3001, path, method, headers: { 'Content-Type': 'application/json', 'Content-Length': data ? Buffer.byteLength(data) : 0 } }, (res: any) => {
      const chunks: any[] = [];
      res.on('data', (c: any) => chunks.push(c));
      res.on('end', () => {
        const raw = Buffer.concat(chunks as any).toString('utf8');
        if (!raw) return resolve(undefined);
        try {
          resolve(JSON.parse(raw));
        } catch (e) {
          reject(e);
        }
      });
    });
    req.on('error', reject);
    if (data) req.write(data);
    req.end();
  });
}

async function runDemo() {
  const bus = new EventBus();
  const userService = new UserService();
  const projectService = new ProjectService();
  const taskService = new TaskService(bus);
  const commentService = new CommentService(bus, {
    getTaskTitle: (taskId: string) => taskService.getById(taskId)?.title,
    getUserName: (userId: string) => userService.getById(userId)?.name,
  });
  const notificationService = new NotificationService(bus, {
    getTaskAssigneeId: (taskId: string) => taskService.getById(taskId)?.assigneeId,
  });

  const server = createServer({ userService, projectService, taskService, commentService, notificationService });
  await new Promise<void>((resolve) => server.listen(3001, resolve));
  console.log('Demo server started on http://localhost:3001');

  // Create users
  const alice = await request('POST', '/users', { name: 'Alice', email: 'alice@example.com' });
  const bob = await request('POST', '/users', { name: 'Bob', email: 'bob@example.com' });
  console.log('Users created:', alice, bob);

  // Create project
  const project = await request('POST', '/projects', { name: 'Build API', description: 'Task management API' });
  console.log('Project created:', project);

  // Add members
  await request('POST', `/projects/${project.id}/members`, { userId: alice.id });
  await request('POST', `/projects/${project.id}/members`, { userId: bob.id });
  const updatedProject = await request('GET', `/projects/${project.id}`);
  console.log('Project members:', updatedProject.memberIds);

  // Create tasks
  const t1 = await request('POST', '/tasks', { title: 'Design', description: 'Design the system', projectId: project.id });
  const t2 = await request('POST', '/tasks', { title: 'Implement', description: 'Code the system', projectId: project.id });
  console.log('Tasks created:', t1, t2);

  // Assign tasks
  await request('PUT', `/tasks/${t1.id}/assign`, { assigneeId: alice.id });
  await request('PUT', `/tasks/${t2.id}/assign`, { assigneeId: bob.id });
  console.log('Tasks assigned');

  // Change status
  await request('PUT', `/tasks/${t1.id}/status`, { status: 'in-progress' });
  await request('PUT', `/tasks/${t1.id}/status`, { status: 'done' });
  console.log('Task 1 progressed to done');

  // Add comments
  await request('POST', '/comments', { taskId: t1.id, authorId: bob.id, body: 'Looks good!' });
  await request('POST', '/comments', { taskId: t2.id, authorId: alice.id, body: 'I can help' });
  console.log('Comments added');

  // Check notifications
  // Allow event loop to process async event bus callbacks
  await new Promise((r) => setTimeout(r, 50));
  const aliceNotifs = await request('GET', `/notifications?userId=${alice.id}`);
  const bobNotifs = await request('GET', `/notifications?userId=${bob.id}`);
  console.log('Alice notifications:', aliceNotifs);
  console.log('Bob notifications:', bobNotifs);

  // Mark first Alice notification as read
  if (aliceNotifs && aliceNotifs.length > 0) {
    const n = await request('PUT', `/notifications/${aliceNotifs[0].id}/read`);
    console.log('Marked as read:', n);
  }

  // List tasks by project
  const projectTasks = await request('GET', `/tasks?projectId=${project.id}`);
  console.log('Tasks by project:', projectTasks.map((t: any) => ({ id: t.id, title: t.title, status: t.status })));

  server.close();
}

runDemo().catch((err) => {
  console.error('Demo error:', err);
  process.exit(1);
});

